package com.ruoyi.warehouse.carriers;

import com.ruoyi.warehouse.support.WarehouseException;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class DpdContractTest {
    static Map<String,Object> address(){return new LinkedHashMap<>(Map.of("name","Synthetic Sender","company","Warehouse","address1","1 Example Street","address2","","town","London","county","","postcode","SW1A1AA","country","GB","phone","020 7000 0000","email","warehouse@example.test"));}
    @Test void addressesKeepDataAndRefuseCustomsOrUnrepresentableDelivery(){var a=DpdContract.address(address());assertEquals("SW1A 1AA",a.get("postcode"));assertEquals("02070000000",a.get("phone"));var bad=address();bad.put("postcode","BT1 1AA");assertThrows(CarrierFailure.class,()->DpdContract.address(bad));bad.put("postcode","SW1A1AA");bad.put("address1","PO BOX 42");assertThrows(CarrierFailure.class,()->DpdContract.address(bad));bad.put("address1","x".repeat(36));assertThrows(WarehouseException.class,()->DpdContract.address(bad));}
    @Test void parcelTotalsUseExactDecimalsAndDocumentedBounds(){assertEquals("0.3",DpdContract.totalWeight(List.of(Map.of("weightKg","0.1"),Map.of("weightKg","0.2"))).toPlainString());assertThrows(CarrierFailure.class,()->DpdContract.totalWeight(List.of(Map.of("weightKg","0.09"))));assertThrows(CarrierFailure.class,()->DpdContract.totalWeight(Collections.nCopies(100,Map.of("weightKg","1"))));}
    @Test void identityRequiresEveryOriginalParcelAndAllowsOpaqueProviderIds(){var c=Map.of("consignmentNumber","opaque-consignment","parcelNumber",List.of("15500000000001","15500000000002"),"parcelIds",List.of("opaque-1","opaque-2"));var id=DpdContract.identity(Map.of("data",Map.of("shipmentId","opaque-shipment","consignments",List.of(c))),2);assertEquals("opaque-shipment",id.get("shipmentId"));assertThrows(CarrierFailure.class,()->DpdContract.identity(Map.of("data",Map.of("shipmentId","opaque-shipment","consignments",List.of(c))),1));assertThrows(CarrierFailure.class,()->DpdContract.opaque("one\ntwo\nthree",40));assertThrows(CarrierFailure.class,()->DpdContract.opaque("bad/identity",40));}
    @Test void originalZplIsNeverAnHtmlOrArbitraryMultiFrameResponse(){String zpl="^XA^FO20,20^FDSYNTHETIC LABEL^FS^XZ";assertEquals(zpl,DpdContract.label(Map.of("data",Map.of("printString",List.of(zpl)))));assertEquals(zpl,DpdContract.label(Map.of("printString",List.of(zpl))));for(String bad:List.of("<html>bad</html>",zpl+zpl,"^XA^XA^XZ^XZ",zpl+"unexpected"))assertThrows(CarrierFailure.class,()->DpdContract.validateLabel(bad));assertThrows(CarrierFailure.class,()->DpdContract.label(Map.of("printString",List.of(zpl),"data",Map.of("printString",List.of(zpl)))));}
    @Test void serviceRequirementsDoNotSilentlySkipMandatoryCustomsOrNotification(){var a=DpdContract.address(address());assertFalse(DpdClient.requirements(Map.of("notifyRequired","N","skuRequired","N"),a));assertThrows(CarrierFailure.class,()->DpdClient.requirements(Map.of("commodityRequired","M"),a));assertThrows(CarrierFailure.class,()->DpdClient.requirements(Map.of("futureRequired","Y"),a));assertThrows(CarrierFailure.class,()->DpdClient.requirements(Map.of("notifyRequired","M"),a));a.put("mobile","07700000000");assertTrue(DpdClient.requirements(Map.of("notifyRequired","M"),a));}
    @Test void shipmentDatesUseLondonCalendarInsteadOfMachineTimezone(){assertEquals("2026-07-02T12:00:00",DpdContract.shipmentDate("2026-07-02",Instant.parse("2026-07-01T23:30:00Z")));assertThrows(CarrierFailure.class,()->DpdContract.shipmentDate("2026-07-01",Instant.parse("2026-07-01T23:30:00Z")));assertThrows(CarrierFailure.class,()->DpdContract.shipmentDate("2026-07-10",Instant.parse("2026-07-01T23:30:00Z")));}
    @Test void vaultBindsCiphertextToConnectionAndNeverReusesWooCommerceContext(){byte[] bytes=new byte[32];new java.security.SecureRandom().nextBytes(bytes);var vault=new CarrierVault(Base64.getEncoder().encodeToString(bytes));var credentials=Map.<String,Object>of("appKey","synthetic-key","appSecret","synthetic-secret");String encrypted=vault.seal("one",credentials);assertEquals(credentials,vault.open("one",encrypted));assertThrows(CarrierFailure.class,()->vault.open("two",encrypted));assertFalse(encrypted.contains("synthetic"));}
    @Test void credentialsCannotBeSilentlyTrimmedOrSplitAtAColon(){for(String key:List.of(" synthetic-key","synthetic-key ","key:unexpected"))assertThrows(WarehouseException.class,()->DpdContract.credentials(Map.of("appKey",key,"appSecret","synthetic-secret")));assertThrows(WarehouseException.class,()->DpdContract.credentials(Map.of("appKey","synthetic-key","appSecret"," secret")));}
    @Test void nullServiceFlagsFailClosedInsteadOfThrowingAnUnclassifiedException(){var flags=new HashMap<String,Object>();flags.put("commodityRequired",null);assertEquals("DPD_SERVICE_REQUIRES_SPECIAL_FLOW",assertThrows(CarrierFailure.class,()->DpdClient.requirements(flags,address())).code());}
    @Test void loopbackOverrideRequiresBothTheTestProfileAndTheLocalServerBind(){var env=new org.springframework.mock.env.MockEnvironment();assertThrows(IllegalStateException.class,()->new CarrierTransport(true,"http://127.0.0.1:18885",env));env.setActiveProfiles("warehouse-carrier-test");assertThrows(IllegalStateException.class,()->new CarrierTransport(true,"http://127.0.0.1:18885",env));env.setProperty("server.address","127.0.0.1");assertTrue(new CarrierTransport(true,"http://127.0.0.1:18885",env).testMode());assertFalse(new CarrierTransport(false,"",env).testMode());assertThrows(CarrierFailure.class,()->new CarrierTransport(false,"",env).client("production",Instant.now().plusSeconds(45)));}
}
